import re

from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone


class ImiClientClock(GenericUnixCommand):
    """Imiclientclock command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Imiclientclock command give parameters of given clock.

        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        :param connection: moler connection to device, terminal when command is executed.
        :param options: is type of clock pass to command.
        """
        super(ImiClientClock, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.options = options
        self.current_ret["RESULT"] = {}
        self.actual_header = ""
        self.time_key = "BEFORE SENDING"
        self.small_headers_table = []

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "imi_client clock"
        cmd = f"{cmd} {self.options}"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._check_clock_type(line)
            except ParsingDone:
                pass
        return super(ImiClientClock, self).on_new_line(line, is_full_line)

    def _check_clock_type(self, line):
        if self.options == "syncE_intf1InUse 0":
            self._parse_time_key_change(line)
            self._parse_main_attributes_header(line)
            self._parse_actual_header(line)
            self._parse_main_attributes(line)
            self._parse_small_headres(line)
            self._parse_parameters_1(line)
            self._parse_parameters_2(line)

    # Sending BM_IM_CHANGE_REQUEST_MSG 'syncE_intf1InUse' new value = 0, request_id = 0
    _re_time_key_change = re.compile(r"^Sending.+")

    def _parse_time_key_change(self, line):
        if self._regex_helper.search_compiled(ImiClientClock._re_time_key_change, line):
            self.time_key = "AFTER SENDING"
            self.current_ret["RESULT"][self.time_key] = {}

            raise ParsingDone

    #     Reference Source Status:
    _re_actual_header = re.compile(r"^.\s{3}(?P<NAME>\w+\s\w+\s\w+):")

    def _parse_actual_header(self, line):
        if self._regex_helper.search_compiled(ImiClientClock._re_actual_header, line):
            self.actual_header = self._regex_helper.group("NAME")
            self.current_ret["RESULT"][self.time_key][self.actual_header] = {}

            raise ParsingDone

    # Received attributes for object /MRBTS-1/FZM_SYNC-1/CLOCK-1
    _re_main_header = re.compile(r"^Rec.+")

    def _parse_main_attributes_header(self, line):
        if self._regex_helper.search_compiled(ImiClientClock._re_main_header, line):
            self.current_ret["RESULT"][self.time_key] = {}
            self.current_ret["RESULT"][self.time_key]["Main attributes"] = {}
            self.actual_header = "Main attributes"

            raise ParsingDone

    #     syncEstablished                     FALSE
    _re_main_attributes = re.compile(r"^.\s{3}(?P<NAME>[a-z]\w+)\s+(?P<VALUE>\w+\s\w+|\w+)")

    def _parse_main_attributes(self, line):
        if self._regex_helper.search_compiled(ImiClientClock._re_main_attributes, line):
            self.current_ret["RESULT"][self.time_key][self.actual_header][self._regex_helper.group("NAME")] = self._regex_helper.group("VALUE")

            raise ParsingDone

    #        outputPort   frequency    enabled
    _re_find_small_headres_line = re.compile(r"(^\s+outputPort|^\s+source)\s+(?P<HEADERS>.+)")

    def _parse_small_headres(self, line):
        if self._regex_helper.search_compiled(ImiClientClock._re_find_small_headres_line, line):
            self.small_headers_table = re.findall(r"\w+", self._regex_helper.group("HEADERS"))

            raise ParsingDone

    #          GNSS       * FALSE
    _re_get_parameters_1 = re.compile(r"^\s{9}(?P<NAME>\w+-\w|\w+)\s+.\s(?P<VAL1>FALSE|TRUE)")

    def _parse_parameters_1(self, line):
        if self._regex_helper.search_compiled(ImiClientClock._re_get_parameters_1, line):
            self.current_ret["RESULT"][self.time_key][self.actual_header][self._regex_helper.group("NAME")] = {}
            self.current_ret["RESULT"][self.time_key][self.actual_header][self._regex_helper.group("NAME")][
                self.small_headers_table[0]
            ] = self._regex_helper.group("VAL1")

            raise ParsingDone

    #          GNSS         * 0       * FALSE
    _re_get_parameters_2 = re.compile(r"^\s{9}(?P<NAME>\w+-\w|\w+)\s+.\s(?P<VAL1>\w+\s\w+|\w+)\s+.\s(?P<VAL2>FALSE|TRUE)")

    def _parse_parameters_2(self, line):
        if self._regex_helper.search_compiled(ImiClientClock._re_get_parameters_2, line):
            self.current_ret["RESULT"][self.time_key][self.actual_header][self._regex_helper.group("NAME")] = {}
            self.current_ret["RESULT"][self.time_key][self.actual_header][self._regex_helper.group("NAME")][
                self.small_headers_table[0]
            ] = self._regex_helper.group("VAL1")
            self.current_ret["RESULT"][self.time_key][self.actual_header][self._regex_helper.group("NAME")][
                self.small_headers_table[1]
            ] = self._regex_helper.group("VAL2")

            raise ParsingDone


